import moment from 'moment'

export default {
  props: [
    'chat',
    'messages',
    'editMessage',
    'mentionList',
    'readOnly',
    'usersList',
    'childrenChats',
  ],
  emits: [
    'edited',
    'enhance',
    'remove',
    'remove-file',
    'hide',
    'answer',
    'run-edit',
    'copy',
    'add-file-to-chat',
    'image',
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'code-file-shown',
    'thread',
    'sub-task',
    'set-active-chat',
    'message-changed',
    'run-agents',
    'search-files',
    'preview-file',
  ],
  data() {
    return {
      showEventsPanel: false,
      activeMessageData: null,
      expandedId: null,
      messageElRefs: [],
      scrollContainerEl: null,
    }
  },
  computed: {
    isVibe() {
      return this.chat.mode === 'vibe'
    }
  },
  mounted() {
    this.scrollContainerEl = this.$refs.scrollContainer
  },
  methods: {
    scrollToBottom() {
      setTimeout(() => this.$refs.anchor?.scrollIntoView({ behavior: 'smooth' }), 200)
    },
    isNewSpeaker(message, ix) {
      if (ix === 0) return true
      const prev = this.messages[ix - 1]
      return prev.role !== message.role || prev.user !== message.user
    },
    setMessageRef(el, ix) {
      // Vue 3 dynamic array refs — collect DOM elements by index
      if (el) {
        this.messageElRefs[ix] = el
      }
    },
    onShowEvents(eventData) {
      this.activeMessageData = eventData
      this.showEventsPanel = true
      this.expandedId = null
    },
    closeEventsPanel() {
      this.showEventsPanel = false
      this.activeMessageData = null
    },
    toggleExpanded(eventId) {
      this.expandedId = this.expandedId === eventId ? null : eventId
    },
    removeAttachment(idx) {
      if (this.activeMessageData && this.activeMessageData.attachments) {
        this.activeMessageData.attachments.splice(idx, 1)
      }
    },
    formatDuration(seconds) {
      if (!seconds) return '0s'
      const baseMoment = moment({ h: 0, m: 0, s: 0, ms: 0 })
      return baseMoment.add(Math.floor(seconds), 'seconds').format('mm:ss')
    }
  }
}
</script>
